def transform(grid):
    g=[row[:] for row in grid]
    # detect horizontal bars by dense row, fill between their endpoints
    bars=[]
    for r,row in enumerate(grid):
        occ=[c for c,v in enumerate(row) if v]
        if len(occ)>=5: bars.append((r,occ))
    for r,occ in bars:
        lo,hi=min(occ),max(occ)
        for c in range(lo,hi+1):
            if grid[r][c]==0:
                l=max(x for x in occ if x<c); q=min(x for x in occ if x>c)
                g[r][c]=grid[r][l] if c-l < q-c else grid[r][q]
    # Each bar gap extends as a ray away from that bar through cells not occupied in input.
    for r,occ in bars:
        for c in range(min(occ),max(occ)+1):
            if grid[r][c]: continue
            l=max(x for x in occ if x<c); q=min(x for x in occ if x>c)
            color=grid[r][l] if c-l < q-c else grid[r][q]
            for step in (-1,1):
