 g=[row[:] for row in a];bars=[]
 for r,row in enumerate(a):
  occ=[c for c,v in enumerate(row) if v]
  if len(occ)>=5:bars.append((r,occ))
 gaps=[]
 for r,occ in bars:
  for c in range(min(occ),max(occ)+1):
   if a[r][c]:continue
   l=max(x for x in occ if x<c);q=min(x for x in occ if x>c)
   color=a[r][l] if c-l<q-c else a[r][q]
   g[r][c]=color;gaps.append((r,c,color))
 # Project gap colors upward; previously completed bar holes remain intact.
 for r,c,color in gaps:
  for rr in range(r-1,-1,-1):
