  if markers:
   mr=min(markers); lowerbars=[br for br,_ in bars if br<mr]
   if lowerbars:
    br=max(lowerbars)
    for rr in range(br+1,mr):
     if g[rr][c]==0:g[rr][c]=a[mr][c]
 return g
