 "content": "def transform(grid):
    """Complete horizontal bars and project the gaps toward the preceding bar."""
    out = [row[:] for row in grid]
    bars = []

    # Dense horizontal rows are bars; their bounded gaps are filled with the
    # bar's color. These are monochrome in the demonstrated task instances.
    for r, row in enumerate(grid):
        occupied = [c for c, value in enumerate(row) if value != 0]
        if len(occupied) >= 5:
            bars.append((r, occupied))
            color = row[occupied[0]]
            for c in range(min(occupied), max(occupied) + 1):
                if row[c] == 0:
                    out[r][c] = color

    # Each gap column extends upward through the space since the previous bar,
    # without changing original cells or other horizontal bars.
    for i, (r, occupied) in enumerate(bars):
        previous_bar = bars[i - 1][0] if i else -1
        color = grid[r][occupied[0]]
        for c in range(min(occupied), max(occupied) + 1):
            if grid[r][c] != 0:
                continue
            for rr in range(r - 1, previous_bar, -1):
                if grid[rr][c] == 0:
                    out[rr][c] = color

    # Vertical markers below the bottom bar continue upward through the
    # intervening blank cells in their own color.
    if bars:
        bottom_bar = bars[-1][0]
        for c in range(len(grid[0])):
            markers = [r for r in range(bottom_bar + 1, len(grid)) if grid[r][c] != 0]
            if markers:
                first = min(markers)
                color = grid[first][c]
                for rr in range(bottom_bar + 1, first):
                    if grid[rr][c] == 0:
                        out[rr][c] = color

    return out
